    vector<bool> submerged(N, false);
    int currentIslands = 0;
    int maxIslands = 0;

    // Process from lowest to highest height
    for (int i = 0; i < N; ) {
        int currentHeight = sections[i].first;
        // process all sections with this height
        while (i < N && sections[i].first == currentHeight) {
            int idx = sections[i].second;
