int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> A(N + 2, 0); // sentinels at both ends are sea
    for (int i = 1; i <= N; ++i) cin >> A[i];

    vector<pair<long long,int>> v;
    v.reserve(N);
    for (int i = 1; i <= N; ++i) v.push_back({A[i], i});
    sort(v.begin(), v.end());

    vector<char> alive(N + 2, 1); // alive = still land at current level just before removing height group
    alive[0] = alive[N + 1] = 0;

    long long islands = 0;
    for (int i = 1; i <= N; ++i) {
        if (A[i] > 0 && !alive[i - 1]) islands++;
    }

    long long ans = islands;

    int p = 0;
    while (p < N) {
        int q = p;
        long long h = v[p].first;
        while (q < N && v[q].first == h) q++;

        // Raise sea level to h: all positions with height h disappear
        for (int k = p; k < q; ++k) {
            int idx = v[k].second;
            bool L = alive[idx - 1];
            bool R = alive[idx + 1];

            if (!L && !R) {
                // single-cell island disappears
                islands--;
            } else if (L && R) {
                // one island splits into two
                islands++;
            }
            // otherwise island count unchanged

            alive[idx] = 0;
        }

        ans = max(ans, islands);
        p = q;
    }

    cout << ans << '\n';
    return 0;
}

