} Section;

int cmp(const void *a, const void *b) {
    return ((Section*)a)->height - ((Section*)b)->height;
}

int main() {
    int N;
    scanf("%d", &N);

    int *A = malloc(N * sizeof(int));
    Section *sections = malloc(N * sizeof(Section));

    for (int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
        sections[i].height = A[i];
        sections[i].index = i;
    }

    qsort(sections, N, sizeof(Section), cmp);

    int *submerged = calloc(N, sizeof(int));
    int islands = 1; // initially all above sea level 0, so one island if N>0
    int maxIslands = 1;

    int prevHeight = 0;
    for (int i = 0; i < N; i++) {
        int idx = sections[i].index;
        int h = sections[i].height;

        if (h == prevHeight) {
            // same height, process all at once
        }

        // submerge this section
        submerged[idx] = 1;

        int leftSubmerged = (idx > 0 && submerged[idx - 1]);
        int rightSubmerged = (idx < N - 1 && submerged[idx + 1]);

        if (leftSubmerged && rightSubmerged) {
            islands--;
        } else if (!leftSubmerged && !rightSubmerged) {
            islands++;
        }
        // else one neighbor submerged -> no change

        if (islands > maxIslands) {
            maxIslands = islands;
        }

        prevHeight = h;
    }

    printf("%d\n", maxIslands);

    free(A);
    free(sections);
    free(submerged);
    return 0;
}

