int parent[200005], rnk[200005];
int find(int x) { return parent[x] == x ? x : (parent[x] = find(parent[x])); }
int unite(int a, int b) {
    a = find(a); b = find(b);
    if (a == b) return 0;
    if (rnk[a] < rnk[b]) { int t = a; a = b; b = t; }
    parent[b] = a;
    if (rnk[a] == rnk[b]) rnk[a]++;
    return 1;
}

