    int *idx = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) idx[i] = i;
    // sort by height descending
    // use qsort
    int *A = a;
    // comparator needs access to a
    // use global or different approach
    // Let's just do it inline

    // Actually let me just iterate over possible sea levels
    // Max height could be large, so let's sort events

    int islands = 0, maxIslands = 0;
    int land[200005]; memset(land, 0, sizeof(land));

    // sort indices by a[i] descending
    for (int i = 0; i < n-1; i++)
        for (int j = i+1; j < n; j++)
            if (a[idx[i]] < a[idx[j]]) { int t = idx[i]; idx[i] = idx[j]; idx[j] = t; }

