        for (int i = p; i < q; i++) {
            int x = idx[i];
            if (x > 0 && land[x-1]) if (unite(x, x-1)) islands--;
            if (x < n-1 && land[x+1]) if (unite(x, x+1)) islands--;
        }
        if (islands > maxIslands) maxIslands = islands;
        p = q;
    }
    printf("%d\n", maxIslands);
    free(idx);
    return 0;
}

