typedef struct {
    int h;
    int idx;
} Node;

int cmp(const void *a, const void *b) {
    const Node *x = (const Node *)a;
    const Node *y = (const Node *)b;
    if (x->h < y->h) return -1;
    if (x->h > y->h) return 1;
    return x->idx - y->idx;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *A = (int *)malloc(sizeof(int) * N);
    Node *v = (Node *)malloc(sizeof(Node) * N);
    char *dead = (char *)calloc(N, sizeof(char));

    for (int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
        v[i].h = A[i];
        v[i].idx = i;
    }

    qsort(v, N, sizeof(Node), cmp);

    int islands = 1;      // at sea level 0, all sections are land in this setting
    int ans = islands;

    int p = 0;
    while (p < N) {
        int q = p;
        int h = v[p].h;
        while (q < N && v[q].h == h) q++;

        // Sections with height h disappear when sea level reaches h
        for (int k = p; k < q; k++) {
            int i = v[k].idx;
            dead[i] = 1;

            int left_land = (i > 0 && !dead[i - 1]);
            int right_land = (i + 1 < N && !dead[i + 1]);

            if (!left_land && !right_land) {
                // A one-section island disappears
                islands--;
            } else if (left_land && right_land) {
                // One island splits into two
                islands++;
            } else {
                // Edge of an island removed, island count unchanged
            }
        }

        if (islands > ans) ans = islands;
        p = q;
    }

    printf("%d\n", ans);

    free(A);
    free(v);
    free(dead);
    return 0;
}

