import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        int[] heights = new int[N];

        // Map from height to list of indices
        TreeMap<Integer, List<Integer>> heightToIndices = new TreeMap<>();
        for (int i = 0; i < N; i++) {
            heights[i] = Integer.parseInt(br.readLine().trim());
            heightToIndices.computeIfAbsent(heights[i], k -> new ArrayList<>()).add(i);
        }

        boolean[] submerged = new boolean[N];
        int islands = 0;
        int maxIslands = 0;

        // Initially, all sections with height > 0 form islands.
        // Check first section.
        if (heights[0] > 0) islands = 1;
        for (int i = 1; i < N; i++) {
            if (heights[i] > 0 && heights[i-1] <= 0) {
                islands++;
            }
        }
        maxIslands = islands;

        // Process heights in increasing order
        for (int h : heightToIndices.keySet()) {
            for (int idx : heightToIndices.get(h)) {
                submerged[idx] = true;
                boolean leftSubmerged = (idx == 0) || submerged[idx - 1];
                boolean rightSubmerged = (idx == N - 1) || submerged[idx + 1];

                if (leftSubmerged && rightSubmerged) {
                    islands--;
                } else if (!leftSubmerged && !rightSubmerged) {
                    islands++;
                }
                // else exactly one neighbor submerged: count unchanged
            }
            maxIslands = Math.max(maxIslands, islands);
        }

        System.out.println(maxIslands);
    }
}

