import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Pair {
        long h;
        int idx;
        Pair(long h, int idx) {
            this.h = h;
            this.idx = idx;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        long[] A = new long[N];
        for (int i = 0; i < N; i++) A[i] = fs.nextLong();

        Pair[] arr = new Pair[N];
        for (int i = 0; i < N; i++) arr[i] = new Pair(A[i], i);
        Arrays.sort(arr, Comparator.comparingLong(p -> p.h));

        boolean[] submerged = new boolean[N]; // true if A[i] <= current sea level
        int islands = 1; // at sea level 0, all sections are land if heights are positive
        int answer = islands;

        int p = 0;
        while (p < N) {
            long h = arr[p].h;
            while (p < N && arr[p].h == h) {
                int i = arr[p].idx;
                boolean leftSub = (i == 0) || submerged[i - 1];
                boolean rightSub = (i == N - 1) || submerged[i + 1];

                if (!leftSub && !rightSub) {
                    // removing middle of an island splits one island into two
                    islands++;
                } else if (leftSub && rightSub) {
                    // removing a single remaining section deletes one island
                    islands--;
                }
                submerged[i] = true;
                p++;
            }
            answer = Math.max(answer, islands);
        }

        System.out.println(answer);
    }
}
